import json
import sys
from pathlib import Path

def convert_and_limit(infile, outfile, n=10):
    rows = []
    with open(infile, 'r') as f:
        for i, line in enumerate(f):
            if i >= n:
                break
            d = json.loads(line)
            obj = {}
            if 'context' in d:
                obj['context'] = d['context']
            if 'completions' in d:
                obj['endings'] = d['completions']
            if 'answer' in d:
                obj['label'] = int(d['answer']) if d['answer'] != "" else -1
            rows.append(obj)
    with open(outfile, 'w') as f:
        json.dump(rows, f, indent=2)

if __name__ == '__main__':
    # Usage: python convert_and_limit.py splitname
    split = sys.argv[1]
    inpath = f'team/data/custom/{split}.jsonl'
    outpath = f'team/data/custom/mcq_{split}.json'
    convert_and_limit(inpath, outpath, 10)

